package cn.zj.zjmarket.test.refund;
import cn.zj.zjmarket.domain.refund.model.Refund.*;
import cn.zj.zjmarket.domain.refund.adapter.port.IRefundChannel;
import cn.zj.zjmarket.domain.refund.adapter.repository.IRefundRepository;
import cn.zj.zjmarket.domain.refund.service.RefundService;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.util.List;
class RefundTests {
 private Request request(int no){return new Request("refund","order","payment","paid-attempt","paid-transaction",1000,"a".repeat(64),"b".repeat(64),"9.00","CNY","attempt-"+no,no);}
 @Test void unknownKeepsOriginalAttempt(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var l=new Lease(request(1),"token",1);when(r.claim("refund")).thenReturn(l);var unknown=new Fact(l.request(),"UNKNOWN",null,null,1);when(c.query(l.request())).thenReturn(unknown);try(var s=new RefundService(r,c,Settings.defaults())){s.recover("refund");}verify(c,never()).execute(any());verify(r).finish(l,unknown);}
 @Test void lostExecuteResponseDefersOriginalLease(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var l=new Lease(request(1),"token",1);when(r.claim("refund")).thenReturn(l);when(r.authorize(l)).thenReturn(true);when(c.execute(l.request())).thenThrow(new IllegalStateException());try(var s=new RefundService(r,c,Settings.defaults())){s.recover("refund");}verify(r).defer(l,false);verify(r,never()).finish(any(),any());}
 @Test void existingSuccessIsQueriedWithoutExecute(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var l=new Lease(request(1),"token",1);var f=new Fact(l.request(),"SUCCEEDED","transaction",2000L,1);when(r.claim("refund")).thenReturn(l);when(c.query(l.request())).thenReturn(f);try(var s=new RefundService(r,c,Settings.defaults())){s.recover("refund");}verify(c,never()).execute(any());verify(r).finish(l,f);}
 @Test void conflictingFactQuarantinesOriginalTask(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var l=new Lease(request(1),"token",1);when(r.claim("refund")).thenReturn(l);when(c.query(any())).thenThrow(new IllegalArgumentException());try(var s=new RefundService(r,c,Settings.defaults())){s.recover("refund");}verify(r).defer(l,true);}
 @Test void oneUnknownDoesNotBlockOtherOrders(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);when(r.due(2)).thenReturn(List.of("one","two"));when(c.notices(2)).thenReturn(List.of());try(var s=new RefundService(r,c,Settings.defaults())){s.tick(2,false);}verify(r).claim("one");verify(r).claim("two");verify(r,never()).discover(anyInt());}
 @Test void noticeCannotSelfReportSuccess(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var n=new Notice("notice","refund","attempt-1","token",0);when(c.notices(1)).thenReturn(List.of(n));when(r.noticeRequest(n)).thenReturn(request(1));when(c.query(request(1))).thenReturn(new Fact(request(1),"UNKNOWN",null,null,1));try(var s=new RefundService(r,c,Settings.defaults())){s.notices(1);}verify(c).retry(n);verify(c,never()).acknowledge(any(),anyBoolean());}
 @Test void settingsRejectUnsafeTimeoutAndRenewal(){assertThrows(IllegalArgumentException.class,()->new Settings(1,30,30,20,1,30,0));assertThrows(IllegalArgumentException.class,()->new Settings(1,10,30,30,1,30,0));assertThrows(IllegalArgumentException.class,()->new Settings(0,10,30,20,1,30,0));}
 @Test void backoffIsBounded(){var s=Settings.defaults();assertTrue(s.delay(1)>=2000&&s.delay(1)<=2250);assertTrue(s.delay(100)>=30000&&s.delay(100)<=30250);}
 @Test void factsRequireFullOriginalBindingAndTime(){var req=request(1);assertThrows(IllegalArgumentException.class,()->new Fact(request(2),"SUCCEEDED","tx",2000L,1).validate(req,3000));assertThrows(IllegalArgumentException.class,()->new Fact(req,"SUCCEEDED","tx",500L,1).validate(req,3000));assertThrows(IllegalArgumentException.class,()->new Fact(req,"SUCCEEDED","tx",4000L,1).validate(req,3000));assertThrows(IllegalArgumentException.class,()->new Fact(req,"FAILED","tx",2000L,1).validate(req,3000));}
 @Test void renewalFailureStopsWriteback(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var l=new Lease(request(1),"token",1);when(r.claim("refund")).thenReturn(l);var renewed=new java.util.concurrent.CountDownLatch(1);when(r.renew(l)).thenAnswer(a->{renewed.countDown();return false;});when(c.query(l.request())).thenAnswer(a->{assertTrue(renewed.await(2,java.util.concurrent.TimeUnit.SECONDS));return new Fact(l.request(),"SUCCEEDED","tx",2000L,1);});try(var service=new RefundService(r,c,new Settings(10,1000,2000,10,1,10,0))){service.recover("refund");}verify(r,never()).finish(any(),any());verify(r,never()).defer(any(),anyBoolean());}
 @Test void changedEligibilityPreventsExecute(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var l=new Lease(request(1),"token",1);when(r.claim("refund")).thenReturn(l);when(r.authorize(l)).thenReturn(false);try(var service=new RefundService(r,c,Settings.defaults())){service.recover("refund");}verify(c,never()).execute(any());verify(r,never()).finish(any(),any());}
 @Test void stableRefundRootAndDistinctAttemptHashes(){var a=request(1);var b=request(2);assertTrue(a.sameRoot(b));assertNotEquals(a.hash(),b.hash());assertEquals(a.hash(),request(1).hash());}
 @Test void checkMissingFactNeverExecutesOrAuthorizes(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var l=new Lease(request(1),"token",1,true);when(r.claim("refund")).thenReturn(l);try(var service=new RefundService(r,c,Settings.defaults())){service.recover("refund");}verify(c,never()).execute(any());verify(r,never()).authorize(any());verify(r).finishCheck(l,null);verify(r,never()).finish(any(),any());}
 @Test void checkUnavailableRetainsOnlyQueryIntent(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var l=new Lease(request(1),"token",1,true);when(r.claim("refund")).thenReturn(l);when(c.query(any())).thenThrow(new IllegalStateException());try(var service=new RefundService(r,c,Settings.defaults())){service.recover("refund");}verify(c,never()).execute(any());verify(r).finishCheck(l,null);verify(r,never()).defer(any(),anyBoolean());}
 @Test void checkExplicitFailureCannotCreateAnotherAttempt(){var r=mock(IRefundRepository.class);var c=mock(IRefundChannel.class);var l=new Lease(request(1),"token",1,true);var fact=new Fact(l.request(),"FAILED","transaction",null,1);when(r.claim("refund")).thenReturn(l);when(c.query(any())).thenReturn(fact);try(var service=new RefundService(r,c,Settings.defaults())){service.recover("refund");}verify(c,never()).execute(any());verify(r).finishCheck(l,fact);}
}
